def merge_open_carts(apps, schema_editor):
    """Collapse duplicate open carts so the unique constraint can be added.

    Per user, the open cart with the greatest ``updated_at`` is kept (a NULL
    ``updated_at`` sorts as the oldest, tie-break: greatest id). CartItem rows of
    the discarded carts move into the kept cart, summing quantities per product,
    so no duplicate (cart, product) row survives. This is lossy by design: the
    merge is not reversible, operators must back up the database first.
    """
    Cart = apps.get_model('shop', 'Cart')
    CartItem = apps.get_model('shop', 'CartItem')

    duplicated_user_ids = list(
        Cart.objects.filter(paid=False)
        .values('user_id')
        .annotate(total=models.Count('id'))
        .filter(total__gt=1)
        .values_list('user_id', flat=True)
    )

    for user_id in duplicated_user_ids:
        carts = list(
            Cart.objects.filter(user_id=user_id, paid=False).order_by('-updated_at', '-id')
        )
        kept_cart, discarded_carts = carts[0], carts[1:]

        for cart in discarded_carts:
            for item in CartItem.objects.filter(cart=cart):
                existing = CartItem.objects.filter(
                    cart=kept_cart, product_id=item.product_id
                ).first()
                if existing is None:
                    item.cart = kept_cart
                    item.save(update_fields=['cart'])
                else:
                    existing.quantity = existing.quantity + item.quantity
                    existing.save(update_fields=['quantity'])
                    item.delete()

        for cart in discarded_carts:
            cart.delete()


